#include <stdio.h>

/* 分段函数求值 */
int fun(int x)
{
    if (x < 1) {
        return x;
    }
    if (x <= 10) {
        return 2 * x - 1;
    }
    if (x <= 100) {
        return 3 * x - 11;
    }
    return x * x - 24;
}

int main(void)
{
    int x;

    scanf("%d", &x);
    printf("The result is:y=%d\n", fun(x));
    return 0;
}

#include <stdio.h>

/* 返回 x 的 n 次幂（n >= 0） */
int mypow(int x, int n)
{
    int result = 1;

    while (n > 0) {
        result *= x;
        n--;
    }
    return result;
}

int main(void)
{
    int x, n;

    scanf("%d%d", &x, &n);
    printf("%d\n", mypow(x, n));
    return 0;
}

#include <stdio.h>

/* 返回正整数 n 的十进制位数 */
int getDigit(long long n)
{
    int len = 0;

    do {
        len++;
        n /= 10;
    } while (n > 0);
    return len;
}

int main(void)
{
    long long n;
    int len;

    scanf("%lld", &n);
    len = getDigit(n);
    if (len > 1) {
        printf("The integer %lld has %d digits.\n", n, len);
    } else {
        printf("The integer %lld has %d digit.\n", n, len);
    }
    return 0;
}

#include <stdio.h>

/* 返回正整数 n 反转后的数 */
int reverseNum(int n)
{
    int r = 0;

    while (n > 0) {
        r = r * 10 + n % 10;
        n /= 10;
    }
    return r;
}

int main(void)
{
    int n;

    scanf("%d", &n);
    printf("The reverse form of number %d is %d.\n", n, reverseNum(n));
    return 0;
}

#include <stdio.h>

/* 把三个整数按升序整理（通过指针修改调用者的变量） */
static void sort3(int *a, int *b, int *c)
{
    int t;

    if (*a > *b) {
        t = *a;
        *a = *b;
        *b = t;
    }
    if (*b > *c) {
        t = *b;
        *b = *c;
        *c = t;
    }
    if (*a > *b) {
        t = *a;
        *a = *b;
        *b = t;
    }
}

/* -1：不是三角形；0：一般三角形；1：直角；2：等腰；3：等边 */
int judgeTriangle(int a, int b, int c)
{
    sort3(&a, &b, &c);
    if (a <= 0 || a + b <= c) {
        return -1;
    }
    if (a == c) {
        return 3;
    }
    if (a * a + b * b == c * c) {
        return 1;
    }
    if (a == b || b == c) {
        return 2;
    }
    return 0;
}

int main(void)
{
    int a, b, c;

    scanf("%d%d%d", &a, &b, &c);
    switch (judgeTriangle(a, b, c)) {
    case -1:
        printf("It is not a triangle.\n");
        break;
    case 0:
        printf("It is a scalenous triangle.\n");
        break;
    case 1:
        printf("It is a right-angled triangle.\n");
        break;
    case 2:
        printf("It is an isosceles triangle.\n");
        break;
    case 3:
        printf("It is a equilateral triangle.\n");
        break;
    default:
        break;
    }
    return 0;
}

#include <stdio.h>

/* 值传递：交换的只是形参副本，不影响调用者 */
void swapByValue(int a, int b)
{
    int t;

    t = a;
    a = b;
    b = t;
}

/* 地址传递：通过指针交换调用者的两个变量 */
void swapByPtr(int *a, int *b)
{
    int t;

    t = *a;
    *a = *b;
    *b = t;
}

int main(void)
{
    int x, y;

    scanf("%d%d", &x, &y);
    printf("before: x=%d y=%d\n", x, y);

    swapByValue(x, y);
    printf("after swapByValue: x=%d y=%d\n", x, y);

    swapByPtr(&x, &y);
    printf("after swapByPtr: x=%d y=%d\n", x, y);
    return 0;
}

#include <stdio.h>

#define MAXN 105

/* 求最大值、最小值及其首次出现的下标（下标从 0 开始） */
void findExtremes(const int a[], int n, int *maxVal, int *maxIdx,
                  int *minVal, int *minIdx)
{
    int i;

    *maxVal = a[0];
    *minVal = a[0];
    *maxIdx = 0;
    *minIdx = 0;
    for (i = 1; i < n; i++) {
        if (a[i] > *maxVal) {
            *maxVal = a[i];
            *maxIdx = i;
        }
        if (a[i] < *minVal) {
            *minVal = a[i];
            *minIdx = i;
        }
    }
}

int main(void)
{
    int n, i;
    int a[MAXN];
    int maxVal, minVal, maxIdx, minIdx;

    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }
    findExtremes(a, n, &maxVal, &maxIdx, &minVal, &minIdx);
    printf("max=%d index=%d\n", maxVal, maxIdx);
    printf("min=%d index=%d\n", minVal, minIdx);
    return 0;
}

#include <stdio.h>

/* 把 4 位整数拆成 4 个数字，下标 0 为千位 */
static void split4(int n, int d[4])
{
    d[0] = n / 1000 % 10;
    d[1] = n / 100 % 10;
    d[2] = n / 10 % 10;
    d[3] = n % 10;
}

/* 把 4 个数字拼回 4 位整数 */
static int join4(const int d[4])
{
    return d[0] * 1000 + d[1] * 100 + d[2] * 10 + d[3];
}

/* 每位加 5 再对 10 取余 */
static void addFive(const int in[4], int out[4])
{
    int i;

    for (i = 0; i < 4; i++) {
        out[i] = (in[i] + 5) % 10;
    }
}

/* 第 1、3 位交换，第 2、4 位交换 */
static void swapPlaces(const int in[4], int out[4])
{
    out[0] = in[2];
    out[1] = in[3];
    out[2] = in[0];
    out[3] = in[1];
}

/* 加密：先每位加 5 取余，再交换位置 */
int encrypt(int n)
{
    int d[4], e[4], s[4];

    split4(n, d);
    addFive(d, e);
    swapPlaces(e, s);
    return join4(s);
}

/* 解密：先把位置换回来，再每位加 5 取余 */
int decrypt(int n)
{
    int d[4], s[4], e[4];

    split4(n, d);
    swapPlaces(d, s);
    addFive(s, e);
    return join4(e);
}

int main(void)
{
    int n;

    scanf("%d", &n);
    printf("encrypted=%d\n", encrypt(n));
    printf("decrypted=%d\n", decrypt(encrypt(n)));
    return 0;
}

#include <stdio.h>

/* f(0) = 0，f(n) = f(n-1) + n 的三次方 */
long long fuc(int n)
{
    if (n <= 0) {
        return 0;
    }
    return fuc(n - 1) + (long long)n * n * n;
}

int main(void)
{
    int n;

    scanf("%d", &n);
    printf("%lld\n", fuc(n));
    return 0;
}

#include <stdio.h>

/* 辗转相除递归求最大公约数 */
long long gcd(long long a, long long b)
{
    if (b == 0) {
        return a;
    }
    return gcd(b, a % b);
}

int main(void)
{
    long long a, b, g;

    scanf("%lld%lld", &a, &b);
    g = gcd(a, b);
    printf("%lld\n", g);
    printf("%lld\n", a / g * b);
    return 0;
}

#include <stdio.h>

/* 把 n 进制的 number 转换成 m 进制并返回（2 <= n, m <= 10） */
int numConvert(int number, int n, int m)
{
    int decimal = 0;
    int base = 1;
    int result = 0;
    int place = 1;
    int digit;

    while (number > 0) {
        digit = number % 10;
        decimal += digit * base;
        base *= n;
        number /= 10;
    }
    while (decimal > 0) {
        result += (decimal % m) * place;
        place *= 10;
        decimal /= m;
    }
    return result;
}

int main(void)
{
    int number, n, m;

    scanf("%d%d%d", &number, &n, &m);
    printf("%d\n", numConvert(number, n, m));
    return 0;
}

#include <stdio.h>

/* 递归求 a 的 e 次幂 */
static int powerRec(int a, int e)
{
    if (e == 0) {
        return 1;
    }
    return a * powerRec(a, e - 1);
}

/* 递归求 s = 1 + a + a^2 + ... + a^(n+1) */
int evaluation(int n, int a)
{
    if (n == 0) {
        return 1 + a;
    }
    return evaluation(n - 1, a) + powerRec(a, n + 1);
}

int main(void)
{
    int n, a;

    scanf("%d%d", &n, &a);
    printf("%d\n", evaluation(n, a));
    return 0;
}

#include <stdio.h>

/* 打印 n 的素数分解式。
   参数 p 表示起始试除因子：主程序调用时传 1（此时由本层输出 "n=" 和行末换行），
   递归调用时传刚找到的素因子 d（此后不再重复输出 "n="）。 */
void printFactor(int n, int p)
{
    int d;

    if (n == 1 && p < 2) {
        printf("1=1\n");
        return;
    }
    d = (p < 2) ? 2 : p;
    while ((long long)d * d <= n && n % d != 0) {
        d++;
    }
    if ((long long)d * d > n) {
        d = n;            /* 剩下的 n 本身就是素数 */
    }
    if (p < 2) {
        printf("%d=", n);
    }
    printf("%d", d);
    if (n / d > 1) {
        printf("*");
        printFactor(n / d, d);
    }
    if (p < 2) {
        printf("\n");
    }
}

int main(void)
{
    int a, b, i;

    scanf("%d%d", &a, &b);
    for (i = a; i <= b; i++) {
        printFactor(i, 1);
    }
    return 0;
}

#include <stdio.h>

/* 递归统计 n 个盘子的最少移动次数：h(0)=0, h(n)=2*h(n-1)+1 */
static long long moveCount(int n)
{
    if (n == 0) {
        return 0;
    }
    return 2 * moveCount(n - 1) + 1;
}

/* 把 n 个盘子从 from 经 via 移到 to，并打印每一步 */
static void hanoi(int n, char from, char to, char via)
{
    if (n == 0) {
        return;
    }
    hanoi(n - 1, from, via, to);
    printf("%c->%c\n", from, to);
    hanoi(n - 1, via, to, from);
}

int main(void)
{
    int n;

    scanf("%d", &n);
    printf("Total moves: %lld\n", moveCount(n));
    hanoi(n, 'A', 'C', 'B');
    return 0;
}

#include <stdio.h>

/* 递归快速幂：返回 (b^e) mod m */
long long powerMod(long long b, long long e, long long m)
{
    long long half, r;

    if (e == 0) {
        return 1 % m;
    }
    half = powerMod(b, e / 2, m);
    r = half * half % m;
    if (e % 2 == 1) {
        r = r * (b % m) % m;
    }
    return r;
}

int main(void)
{
    long long b, e, m;

    scanf("%lld%lld%lld", &b, &e, &m);
    printf("%lld\n", powerMod(b, e, m));
    return 0;
}

#include <stdio.h>

#define MAXN 10

static int n;
static int used[MAXN];
static int perm[MAXN];

/* 递归按字典序输出 1..n 的全排列 */
static void dfs(int depth)
{
    int i;

    if (depth == n) {
        for (i = 0; i < n; i++) {
            printf("%d", perm[i]);
            if (i != n - 1) {
                printf(" ");
            }
        }
        printf("\n");
        return;
    }
    for (i = 1; i <= n; i++) {
        if (!used[i]) {
            used[i] = 1;
            perm[depth] = i;
            dfs(depth + 1);
            used[i] = 0;
        }
    }
}

int main(void)
{
    scanf("%d", &n);
    dfs(0);
    return 0;
}
